pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for leaving a "dead zone" (small slivers that are hard to fill).
    // Specifically, residuals between 1 and 9 are extremely difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Reward placements that create a residual perfectly divisible by a common factor,
    // or that leave a "nice" clean remainder for future items.
    if post_residual % 25 == 0 {
        score -= 15.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual,
    // we prioritize this bin heavily to avoid leaving the next item for a new bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;

        // If the next item fits perfectly (zero waste), reward even more.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // If this is the only bin that fits the current item, avoid opening a new bin
    // unless the post_residual is truly abysmal (e.g., < 5).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 5 {
            score += 20.0;
        } else {
            score -= 60.0;
        }
    }

    // New bin candidate handling:
    // Only open a new bin if the mean residual of current bins is very low,
    // or if the current item is large and would leave a tiny, useless remainder.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else if mean_residual < 15.0 && item_size < 70 {
            // Penalize opening a new bin if we have plenty of capacity elsewhere.
            score += 100.0;
        } else {
            score += 45.0;
        }
    }

    // Favor bins that are already partially full (higher density).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    // We want to minimize the post_residual to pack tightly.
    let mut score = post;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic penalty
    // that decreases as the stream progresses (to favor new bins later when space is fragmented).
    if bin_residual == bin_capacity {
        score += (bin_capacity as f64) * (1.2 - 0.5 * progress);
    }

    // Lookahead logic:
    // If we have a next_item, penalize placements that create a post_residual 
    // that is too small to fit the next_item (dead space creation).
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += (next_item_size as f64 - post) * 1.5;
        }
    }

    // Interaction with mean_residual:
    // Penalize bins that deviate significantly from the mean_residual
    // to keep the packing density uniform across open bins.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.2;

    // Favor bins that are the "last chance" (fitting_bins_count == 1)
    // to avoid leaving them underutilized if they can accommodate the current item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Non-linear coupling: penalize very small residuals (slivers) 
    // which are harder to fill later, amplified by stream progress.
    if post < 10.0 {
        score += (10.0 - post) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize large gaps that are likely to remain unusable (dead space).
    // As the stream progresses, we become more conservative about creating small gaps.
    let gap_penalty = post.powf(1.5) * (1.0 + progress);

    // Favor bins that leave a residual closest to the expected future item size,
    // weighted by the scarcity of fitting bins.
    let fit_pressure = if fitting_bins_count > 0 {
        1.0 / (fitting_bins_count as f64).sqrt()
    } else {
        100.0 // High penalty for new bin candidate if not strictly necessary
    };

    let lookahead_alignment = if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        diff * (1.0 - progress)
    } else {
        0.0
    };

    // Evaluate the cost of opening a new bin vs filling existing ones.
    let is_new_bin = bin_residual == bin_capacity;
    let base_score = if is_new_bin {
        // Only open a new bin if the average residual of current bins is poor
        // and we are not near the end of the stream.
        let new_bin_cost = 45.0 + (mean_residual * 0.5) + (progress * 20.0);
        new_bin_cost
    } else {
        gap_penalty + (lookahead_alignment * 0.8) + (fit_pressure * 5.0)
    };

    base_score
}

