pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-inspired Best-Fit with Lookahead Pressure
    // We prioritize bins that result in a post_residual that is either 0 (perfect fit)
    // or a value that is highly compatible with the lookahead (next_item_size).

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Penalty for opening new bins: if we have bins that can fit, 
    // discourage the new bin unless the current item is very large.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 150.0 + (item_size as f64 * 1.5);
        } else {
            score -= 20.0; // Bias towards opening a new bin if nothing else fits
        }
    } else {
        // 2. Harmonic/Modulo optimization:
        // We want to leave space that is likely to be filled by the next item.
        // A smaller post_residual is usually good, but if post_residual < next_item_size,
        // it creates "dead space" that cannot be filled by the lookahead.
        if next_item_size > 0 {
            if post_residual < next_item_size {
                // Penalize fragmenting the bin such that the next item cannot fit
                score += (next_item_size - post_residual) as f64 * 1.2;
            } else {
                // Reward leaving space that perfectly matches the lookahead
                score -= (post_residual - next_item_size) as f64 * 0.5;
            }
        }

        // 3. Pressure from bin count:
        // As we progress, if open_bins_count is high, prioritize tighter packing.
        let progress = step_index as f64 / total_items as f64;
        score += (open_bins_count as f64 * progress) * 2.0;

        // 4. Harmonic alignment: 
        // Penalize residuals that are not multiples of common item size fractions
        // to keep the bin "cleaner" for future items.
        if post_residual % 10 != 0 {
            score += 5.0;
        }
    }

    score
}
